# and cell type annotations in `celltype`.

import os
import numpy as np
import pandas as pd

# Try to locate a loaded spatial object and the reference object
assert 'sc_ref' in globals(), "Reference object `sc_ref` not found in the current session."
ref = sc_ref

# Heuristically find the active spatial dataset in memory
candidate_names = [
    name for name, obj in globals().items()
    if name != 'sc_ref' and hasattr(obj, 'obs') and hasattr(obj, 'var') and hasattr(obj, 'X')
]
assert len(candidate_names) > 0, "No spatial AnnData object found in the current session."
spatial_name = candidate_names[0]
adata = globals()[spatial_name]

# Validate reference metadata
assert 'celltype' in ref.obs.columns, "`celltype` not found in sc_ref.obs."

# Prefer running via tangram if RCTD wrapper is unavailable; otherwise use spacexr/RCTD if installed.
