    sc.tl.diffmap(adata)
if 'dpt_pseudotime' not in adata.obs:
    sc.tl.dpt(adata)

cluster_key = next((k for k in ['cell_type', 'celltype', 'annotation', 'annotations', 'cluster', 'clusters', 'leiden'] if k in adata.obs.columns), None)
