    sc.tl.leiden(adata, key_added='leiden')
    cluster_key = 'leiden'

use_velocity = set(['spliced', 'unspliced']).issubset(set(adata.layers.keys()))
method = 'pseudotime'

if use_velocity:
    try:
        scv.pp.moments(adata, n_pcs=min(30, adata.obsm['X_pca'].shape[1]), n_neighbors=30)
        scv.tl.velocity(adata, mode='stochastic')
        scv.tl.velocity_graph(adata)
        vk = cr.kernels.VelocityKernel(adata).compute_transition_matrix()
        pk = cr.kernels.PseudotimeKernel(adata, time_key='dpt_pseudotime').compute_transition_matrix()
        kernel = 0.8 * vk + 0.2 * pk
