colors = ['dpt_pseudotime', cluster_key, 'cellrank_dominant_fate']
sc.pl.umap(adata, color=colors, ncols=2, show=False)
plt.savefig(summary_plot, dpi=200, bbox_inches='tight')
plt.close()

fate_cols = [f'cellrank_fate_{str(c)}' for c in fate_df.columns[:min(4, fate_df.shape[1])]]
