required = {'chromosome', 'start', 'end'}
if not required.issubset(set(adata.var.columns)):
    annotated = False
    for organism in ['hsapiens', 'mmusculus']:
        try:
            cnv.io.genomic_position_from_biomart(adata, organism=organism)
            if required.issubset(set(adata.var.columns)):
                annotated = True
                print(f'Annotated genomic positions using biomart: {organism}')
                break
        except Exception as e:
