{"code": "import os, glob, json, sys, subprocess
from pathlib import Path
import numpy as np, pandas as pd, scanpy as sc

cands = glob.glob('**/*.h5ad', recursive=True)
if not cands:
    raise FileNotFoundError('No .h5ad file found in the working directory')

def rank_path(p):
    name = Path(p).name.lower()
    score = 0
    for kw, w in [('annot', 5), ('celltype', 4), ('label', 4), ('preprocess', 3), ('spatial', 2), ('adata', 1)]:
        if kw in name:
            score += w
    return (score, os.path.getmtime(p))

adata_path = sorted(cands, key=rank_path, reverse=True)[0]
adata = sc.read_h5ad(adata_path)

if 'cell_type' not in adata.obs.columns:
    raise KeyError("Expected cell type annotations in adata.obs['cell_type']")

labels = adata.obs['cell_type'].astype(str)
labels_lower = labels.str.lower()
ref_mask = labels_lower.str.contains('t cell|t-cell|t cells|b cell|b-cell|b cells', regex=True)
if not ref_mask.any():
    ref_mask = ((labels_lower.str.contains('t') & labels_lower.str.contains('cell')) | (labels_lower.str.contains('b') & labels_lower.str.contains('cell')))
ref_cats = sorted(labels[ref_mask].unique().tolist())
if len(ref_cats) == 0:
    raise ValueError('Could not identify T-cell/B-cell reference categories from adata.obs[\'cell_type\']')

try:
    import infercnvpy as cnv
except Exception:
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', 'infercnvpy', 'mygene'])
    import infercnvpy as cnv

req = {'chromosome', 'start', 'end'}
if not req.issubset(set(adata.var.columns)):
    try:
        import mygene
        genes = pd.Index(adata.var_names.astype(str))
        sample_genes = genes[: min(1000, len(genes))]
        human_like = np.mean([g.upper() == g and any(ch.isalpha() for ch in g) for g in sample_genes]) if len(sample_genes) else 1.0
        mouse_like = np.mean([(len(g) > 1 and g[0].isupper() and g[1:].lower() == g[1:]) for g in sample_genes]) if len(sample_genes) else 0.0
        species = 'human' if human_like >= mouse_like else 'mouse'
        mg = mygene.MyGeneInfo()
        res = mg.querymany(genes.tolist(), scopes='symbol,ensemblgene', fields='symbol,genomic_pos,genomic_pos_hg38,genomic_pos_hg19,genomic_pos_mm10', species=species, as_dataframe=True, df_index=True, returnall=False, verbose=False)
        if not isinstance(res, pd.DataFrame):
            res = pd.DataFrame(res)
        def pick_pos(row):
            for k in ['genomic_pos_hg38', 'genomic_pos_hg19', 'genomic_pos_mm10', 'genomic_pos']:
                if k in row.index and pd.notna(row[k]):
                    v = row[k]
                    if isinstance(v, list) and len(v) > 0:
                        v = v[0]
                    if isinstance(v, dict):
                        return pd.Series({'chromosome': str(v.get('chr')), 'start': v.get('start'), 'end': v.get('end')})
            return pd.Series({'chromosome': np.nan, 'start': np.nan, 'end': np.nan})
        pos = res.apply(pick_pos, axis=1)
        pos = pos.groupby(pos.index).first()
        adata.var = adata.var.join(pos, how='left')
    except Exception as e:
        raise RuntimeError(f'Failed to annotate genomic coordinates required for CNV inference: {e}')

if not req.issubset(set(adata.var.columns)):
    raise ValueError('Genomic coordinates are still missing after annotation attempt')

keep = adata.var['chromosome'].notna() & adata.var['start'].notna() & adata.var['end'].notna()
adata = adata[:, keep].copy()
adata.var['chromosome'] = adata.var['chromosome'].astype(str).str.replace('chr', '', regex=False)
adata.var['start'] = pd.to_numeric(adata.var['start'], errors='coerce')
adata.var['end'] = pd.to_numeric(adata.var['end'], errors='coerce')
adata = adata[:, adata.var.sort_values(['chromosome', 'start', 'end']).index].copy()

cnv.tl.infercnv(adata, reference_key='cell_type', reference_cat=ref_cats, window_size=100, n_jobs=4)

cnv_key = None
for k in adata.obsm.keys():
    if 'cnv' in str(k).lower():
        cnv_key = k
        break
if cnv_key is not None:
    X = adata.obsm[cnv_key]
    adata.obs['cnv_burden'] = np.asarray(np.abs(X).mean(axis=1)).ravel()

outdir = Path('cnv_inference')
outdir.mkdir(parents=True, exist_ok=True)
out_h5ad = outdir / 'adata_with_cnv.h5ad'
adata.write(out_h5ad)

try:
    import matplotlib.pyplot as plt
    if 'X_umap' in adata.obsm and 'cnv_burden' in adata.obs.columns:
        sc.pl.umap(adata, color=['cell_type', 'cnv_burden'], show=False)
        plt.savefig(outdir / 'cnv_umap.png', dpi=200, bbox_inches='tight')
        plt.close('all')
except Exception:
    pass

try:
    import matplotlib.pyplot as plt
    cnv.pl.chromosome_heatmap(adata, groupby='cell_type', show=False)
    plt.savefig(outdir / 'cnv_chromosome_heatmap.png', dpi=200, bbox_inches='tight')
    plt.close('all')
except Exception:
    pass

print(json.dumps({'input_h5ad': adata_path, 'reference_categories': ref_cats, 'output_h5ad': str(out_h5ad)}))"}
